#![allow(dead_code)]
use alloy_primitives::U256;
use std::{fs,io::Write,time::Instant};
struct Modulus{modulus:U256}
fn secp256k1()->Modulus{Modulus{modulus:U256::from_str_radix("fffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f",16).unwrap()}}
include!("../rail_advisory_reference.rs");
#[derive(Clone,Copy)]#[repr(C)]struct RailStep{w:u32,n0:u32,n1:u32,n2:u32,nb:u32,anchor:u32}
extern "C"{fn rail8_population(steps:*const RailStep,n:usize,pairs:*const u64,count:usize,flags:*mut u8)->i32;}
fn main(){assert!(std::is_x86_feature_detected!("avx512f")&&std::is_x86_feature_detected!("avx512dq"));assert_eq!(std::mem::size_of::<RailStep>(),24);let a:Vec<String>=std::env::args().collect();let r=RailAdvisory::new(&a[1]);assert!(r.anchors.len()>=r.steps.len());let steps:Vec<RailStep>=r.steps.iter().zip(&r.anchors).map(|(s,anchor)|RailStep{w:s[0]as u32,n0:s[1]as u32,n1:s[2]as u32,n2:s[3]as u32,nb:s[4]as u32,anchor:*anchor as u32}).collect();
 let text=fs::read_to_string(&a[2]).unwrap();let mut denominators=Vec::new();let mut expected=Vec::new();let t=Instant::now();let mut counts=[0usize;4];for line in text.lines().filter(|l|!l.is_empty()&&!l.starts_with('#')){let v:Vec<&str>=line.split_whitespace().collect();if v[0]=="batch"{continue;}let num=|k:usize|U256::from_str_radix(v[k].trim_start_matches("0x"),16).unwrap();let tx=num(4);let ox=num(6);let ex=num(8);let d1=r.sub(tx,ox);let d2=r.sub(ox,ex);denominators.extend_from_slice(d1.as_limbs());denominators.extend_from_slice(d2.as_limbs());let flag=r.flags((tx,U256::ZERO),(ox,U256::ZERO),(ex,U256::ZERO));counts[flag as usize]+=1;expected.push(flag);}
 let scalar=t.elapsed().as_secs_f64();println!("SCALAR_REFERENCE shots={} flags={counts:?} seconds={scalar:.6} us_per_shot={:.6}",expected.len(),scalar*1e6/expected.len()as f64);let mut output=vec![0u8;expected.len()];let mut best=f64::INFINITY;for rep in 0..3{let t=Instant::now();let code=unsafe{rail8_population(steps.as_ptr(),steps.len(),denominators.as_ptr(),expected.len(),output.as_mut_ptr())};assert_eq!(code,0);let dt=t.elapsed().as_secs_f64();best=best.min(dt);let mut bad=0;for(i,(x,y))in output.iter().zip(&expected).enumerate(){if x!=y{if bad<16{eprintln!("MISMATCH shot={i} got={x} expected={y}");}bad+=1;}}println!("SIMD_REFERENCE_DIFF rep={rep} shots={} mismatches={bad} seconds={dt:.6} us_per_shot={:.6}",expected.len(),dt*1e6/expected.len()as f64);if bad!=0{fs::write("mismatch-output.bin",&output).unwrap();panic!("SIMD mismatch {bad}");}}
 let mut f=fs::File::create("denominator-pairs.bin").unwrap();for w in &denominators{f.write_all(&w.to_le_bytes()).unwrap();}fs::write("reference-flags.bin",&expected).unwrap();let mut f=fs::File::create("steps.bin").unwrap();for s in &steps{for w in [s.w,s.n0,s.n1,s.n2,s.nb,s.anchor]{f.write_all(&w.to_le_bytes()).unwrap();}}
 // Extra signed-limb edges and a final partial vector exercise padding.
 let mut edge=Vec::new();let mut exp=Vec::new();let mut values=vec![U256::ZERO,U256::from(1),U256::from(2),r.p-U256::from(1),r.p-U256::from(2)];for k in 0..256{values.push(U256::from(1)<<k);}for i in 0..values.len(){let d1=values[i];let d2=values[(i*37+3)%values.len()];edge.extend_from_slice(d1.as_limbs());edge.extend_from_slice(d2.as_limbs());let(a,b)=r.rail_walk(d1,true);let(c,d)=r.rail_walk(d2,false);exp.push(u8::from(a||c)|(u8::from(b||d)<<1));}let mut out=vec![0;exp.len()];assert_eq!(unsafe{rail8_population(steps.as_ptr(),steps.len(),edge.as_ptr(),exp.len(),out.as_mut_ptr())},0);assert_eq!(out,exp,"edge rail flags");println!("EDGES_PASS shots={} partial_final_vector=true",out.len());println!("RESULT exact_flags=true shots={} speedup={:.6} best_us_per_shot={:.6} advisory_only=true direct_rejection=false",expected.len(),scalar/best,best*1e6/expected.len()as f64);
}
